export const ORDER=['U','R','F','D','L','B'];
export const SCAN_ORDER=['F','R','B','L','U','D'];
export const INFO={U:{name:'Top',color:'White',hex:'#f1f3ed',edge:'Blue',hint:'Tilt the cube toward you. The green face belongs along the bottom edge.'},R:{name:'Right',color:'Red',hex:'#f2685c',edge:'White',hint:'Show the red center. Keep the white face above it.'},F:{name:'Front',color:'Green',hex:'#48c795',edge:'White',hint:'Show the green center. Keep the white face above it.'},D:{name:'Bottom',color:'Yellow',hex:'#f0ce54',edge:'Green',hint:'Tilt the cube away from you. The green face belongs along the top edge.'},L:{name:'Left',color:'Orange',hex:'#f59c4e',edge:'White',hint:'Show the orange center. Keep the white face above it.'},B:{name:'Back',color:'Blue',hex:'#689bed',edge:'White',hint:'Show the blue center. Keep the white face above it.'}};
export const SOLVED=ORDER.map(f=>f.repeat(9)).join('');
export function blankFaces(){return Object.fromEntries(ORDER.map(f=>[f,Array.from({length:9},(_,i)=>i===4?f:'?')]));}
export function fromString(s){return Object.fromEntries(ORDER.map((f,i)=>[f,s.slice(i*9,i*9+9).split('')]));}
export function toString(f){return ORDER.map(k=>f[k].join('')).join('');}
export function rotateFace(a){return [a[6],a[3],a[0],a[7],a[4],a[1],a[8],a[5],a[2]];}
export function validate(s,Cube){
 if(typeof s!=='string'||s.length!==54||/[^URFDLB]/.test(s))return {ok:false,message:'Some stickers still need a color. Finish all six faces first.'};
 const wrong=ORDER.filter(f=>s.split(f).length-1!==9);
 if(wrong.length)return {ok:false,message:'A cube needs exactly 9 stickers of each color. Check '+wrong.map(f=>INFO[f].color.toLowerCase()+' ('+(s.split(f).length-1)+')').join(', ')+'.'};
 if(ORDER.some((f,i)=>s[i*9+4]!==f))return {ok:false,message:'Check the center colors and the selected face. Use white on top and green in front.'};
 const c=Cube.fromString(s),parity=a=>a.reduce((v,x,i)=>v+a.slice(i+1).filter(y=>y<x).length,0)%2;
 if(c.asString()!==s||new Set(c.cp).size!==8||new Set(c.ep).size!==12)return {ok:false,message:'These colors do not form all the cube’s pieces. Check the photos, especially red vs. orange, and each face’s rotation.'};
 if(c.co.reduce((a,b)=>a+b,0)%3||c.eo.reduce((a,b)=>a+b,0)%2||parity(c.cp)!==parity(c.ep))return {ok:false,message:'This arrangement cannot be solved with ordinary turns. Check the colors and orientation of each face first. A rotated scan is a common cause.'};
 return {ok:true,solved:c.isSolved()};
}
export function explain(move){const face=INFO[move[0]].name.toLowerCase();return move.endsWith('2')?`Turn the ${face} face halfway around (180°). Either direction works.`:`Turn the ${face} face a quarter-turn ${move.endsWith("'")?'counterclockwise':'clockwise'}, looking straight at that face.`;}
export function hsv([r,g,b]){r/=255;g/=255;b/=255;let max=Math.max(r,g,b),min=Math.min(r,g,b),d=max-min,h=0;if(d){if(max===r)h=((g-b)/d)%6;else if(max===g)h=(b-r)/d+2;else h=(r-g)/d+4;h*=60;if(h<0)h+=360;}return [h,max===0?0:d/max,max];}
export function classify(rgb){const [h,s,v]=hsv(rgb);if(v<.13)return {color:'?',confidence:0};if(s<.23&&v>.38)return {color:'U',confidence:Math.min(1,(.36-s)*4)};let color=h<12||h>=345?'R':h<42?'L':h<78?'D':h<169?'F':h<270?'B':'R';const centers={R:0,L:28,D:57,F:127,B:215};let distance=Math.abs(h-centers[color]);distance=Math.min(distance,360-distance);return {color,confidence:Math.max(.15,Math.min(1,s*1.7)*(1-Math.min(distance,50)/80))};}
export function sampleGrid(ctx,x,y,size){let colors=[],confidence=[],rgbs=[],uniform=[];for(let r=0;r<3;r++)for(let c=0;c<3;c++){let cx=x+(c+.5)*size/3,cy=y+(r+.5)*size/3,p=Math.max(4,Math.round(size/3*.20));let data=ctx.getImageData(Math.round(cx-p/2),Math.round(cy-p/2),p,p).data;let channels=[[],[],[]];for(let i=0;i<data.length;i+=4)for(let ch=0;ch<3;ch++)channels[ch].push(data[i+ch]);let rgb=channels.map(ch=>ch.sort((a,b)=>a-b)[Math.floor(ch.length/2)]);let dev=channels.reduce((acc,ch,k)=>acc+ch.reduce((a,b)=>a+Math.abs(b-rgb[k]),0)/ch.length,0)/3;let result=classify(rgb);rgbs.push(rgb);colors.push(result.color);confidence.push(result.confidence);uniform.push(dev<31);}return {colors,confidence,rgbs,uniform};}
export function stickerPose(face,r,c){switch(face){case'U':return {pos:[c-1,1,r-1],normal:[0,1,0]};case'D':return {pos:[c-1,-1,1-r],normal:[0,-1,0]};case'F':return {pos:[c-1,1-r,1],normal:[0,0,1]};case'B':return {pos:[1-c,1-r,-1],normal:[0,0,-1]};case'R':return {pos:[1,1-r,1-c],normal:[1,0,0]};case'L':return {pos:[-1,1-r,c-1],normal:[-1,0,0]};}}
export const TURNS={U:{axis:'y',sign:1},D:{axis:'y',sign:-1},R:{axis:'x',sign:1},L:{axis:'x',sign:-1},F:{axis:'z',sign:1},B:{axis:'z',sign:-1}};
export function lab(rgb){let [r,g,b]=rgb.map(v=>{v/=255;return v>.04045?((v+.055)/1.055)**2.4:v/12.92;});let xyz=[(r*.4124+g*.3576+b*.1805)/.95047,r*.2126+g*.7152+b*.0722,(r*.0193+g*.1192+b*.9505)/1.08883].map(v=>v>.008856?Math.cbrt(v):7.787*v+16/116);return [116*xyz[1]-16,500*(xyz[0]-xyz[1]),200*(xyz[1]-xyz[2])];}
export function calibrate(samples){if(!ORDER.every(f=>samples[f]?.rgbs?.[4]))return null;const centers=Object.fromEntries(ORDER.map(f=>[f,lab(samples[f].rgbs[4])]));let result={},uncertain={};for(let f of ORDER){result[f]=[];uncertain[f]=[];samples[f].rgbs.forEach((rgb,i)=>{if(i===4){result[f].push(f);return;}const value=lab(rgb);const distances=ORDER.map(k=>({color:k,d:Math.hypot((value[0]-centers[k][0])*.5,value[1]-centers[k][1],value[2]-centers[k][2])})).sort((a,b)=>a.d-b.d);result[f].push(distances[0].color);if(distances[1].d-distances[0].d<9||distances[0].d>35)uncertain[f].push(i);});}return {faces:result,uncertain};}
